query SizingArticleRead($id: ID!) {
 shop { id myshopifyDomain ianaTimezone }
 shopLocales { locale primary published }
 article(id: $id) {
  id handle title body summary tags isPublished publishedAt createdAt updatedAt templateSuffix
  blog { id handle }
  author { name }
  image { id url altText width height }
 }
}
